/**
 * What a visitor sees when they aim at a door, and the dot they aim with.
 *
 * A door is an entity with a link. Aimed at, it gets a small card:
 *
 *   Subway station           the door's name, which the world's author wrote
 *   On worlds.example        the site it leads to
 *   Click to go through      what to do
 *
 * The second line is the one the author does not write. It is the host of
 * the address this client resolved the link to, so a door named "Back to
 * the lobby" that leads somewhere else says where it really leads.
 *
 * The card sits at the pointer while the pointer is free, and in the middle
 * of the view, under the aiming dot, once the world holds the pointer. It
 * takes no click: the click is the world's.
 *
 * This is DOM only, and it is not part of the first paint: the code that
 * aims at doors asks for it the first time there is something to show
 * (portalInteraction.ts). The nodes are made once and reused. The colours
 * follow the device's look, and a page may set its own through the
 * `--webverse-portal-*` properties.
 */

/** The card. */
export const PORTAL_CARD_ATTR = 'data-webverse-portal-card';
/** The line of the card that holds the door's name, as text. */
export const PORTAL_LABEL_ATTR = 'data-webverse-portal-label';
/** The aiming dot. */
export const PORTAL_RETICLE_ATTR = 'data-webverse-portal-reticle';

/** A point in the view, in CSS pixels from its top left corner. */
export interface PortalPoint {
  x: number;
  y: number;
}

export interface PortalOverlay {
  /**
   * Show the card for a door. `name` is the author's text for it; `href` is
   * the address the client resolved its link to, from which the card works
   * out the site; `at` is the pointer, or null to sit in the middle.
   */
  showFocus(name: string, href: string, at: PortalPoint | null): void;
  /** Move the card: to the pointer, or to the middle when null. */
  placeFocus(at: PortalPoint | null): void;
  hideFocus(): void;
  /** The aiming dot, shown while the world holds the pointer. */
  setReticleVisible(visible: boolean): void;
  dispose(): void;
}

/** The site an address is on, as a visitor reads one: its host. Empty for anything that names no site. */
export function doorSite(href: string): string {
  try {
    const url = new URL(href);
    return url.protocol === 'https:' || url.protocol === 'http:' ? url.host : '';
  } catch {
    return '';
  }
}

/** How far from the pointer the card's corner sits, in CSS pixels. */
const POINTER_GAP = 16;
/** How near an edge of the window the card may come. */
const EDGE_MARGIN = 12;
/**
 * Room kept at the bottom of a wide window. A page that frames this one may
 * float a bar of its own there; this page cannot know, so it keeps clear.
 */
const BOTTOM_ROOM = 80;
/** Up to this width a window is a narrow one, where such a bar is at the top. */
const NARROW_WIDTH = 720;

/**
 * Where the card's top left corner goes for a pointer at `at`: down and to
 * the right of it where there is room, to the left of it or above it where
 * there is not, and never off an edge of the window.
 */
export function cardCorner(at: PortalPoint, size: { width: number; height: number }, view: { width: number; height: number }): { left: number; top: number } {
  const right = view.width - EDGE_MARGIN;
  const bottom = view.height - (view.width > NARROW_WIDTH ? BOTTOM_ROOM : EDGE_MARGIN);
  let left = at.x + POINTER_GAP;
  if (left + size.width > right) left = at.x - POINTER_GAP - size.width;
  let top = at.y + POINTER_GAP;
  if (top + size.height > bottom) top = at.y - POINTER_GAP - size.height;
  return {
    left: Math.max(EDGE_MARGIN, Math.min(left, right - size.width)),
    top: Math.max(EDGE_MARGIN, Math.min(top, bottom - size.height)),
  };
}

export function createPortalOverlay(doc: Document): PortalOverlay {
  let disposed = false;
  const dark = doc.defaultView?.matchMedia?.('(prefers-color-scheme: dark)').matches ?? true;

  const reticle = doc.createElement('div');
  reticle.setAttribute(PORTAL_RETICLE_ATTR, '');
  reticle.style.cssText =
    'position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);z-index:9;' +
    'width:6px;height:6px;border-radius:50%;pointer-events:none;display:none;' +
    'background:var(--webverse-portal-reticle,rgba(223,227,234,0.85));' +
    'box-shadow:0 0 0 1px rgba(0,0,0,0.4);';
  doc.body.appendChild(reticle);

  const card = doc.createElement('div');
  card.setAttribute(PORTAL_CARD_ATTR, '');
  card.setAttribute('role', 'status');
  card.setAttribute('aria-live', 'polite');
  card.style.cssText =
    'position:fixed;z-index:9;display:none;pointer-events:none;box-sizing:border-box;' +
    'max-width:min(70vw,360px);padding:14px 18px;border-radius:18px;' +
    'font:16px/1.4 "Source Sans 3",system-ui,sans-serif;' +
    `background:var(--webverse-portal-bg,${dark ? 'rgba(24,24,30,0.72)' : 'rgba(255,255,255,0.72)'});` +
    `color:var(--webverse-portal-fg,${dark ? '#d6d2c8' : '#3a372f'});` +
    `border:1px solid var(--webverse-portal-border,${dark ? 'rgba(255,255,255,0.18)' : 'rgba(255,255,255,0.75)'});` +
    `box-shadow:0 8px 32px rgba(0,0,0,${dark ? '0.5' : '0.28'});` +
    '-webkit-backdrop-filter:blur(20px) saturate(180%);backdrop-filter:blur(20px) saturate(180%);';
  const line = (css: string): HTMLDivElement => {
    const node = doc.createElement('div');
    node.style.cssText = `overflow:hidden;text-overflow:ellipsis;white-space:nowrap;${css}`;
    card.appendChild(node);
    return node;
  };
  const name = line(`font:700 20px/1.2 Inter,system-ui,sans-serif;color:var(--webverse-portal-name,${dark ? '#f4f2ec' : '#1f1d1a'});`);
  name.setAttribute(PORTAL_LABEL_ATTR, '');
  const site = line('margin-top:4px;');
  const what = line('margin-top:2px;');
  what.textContent = 'Click to go through';
  doc.body.appendChild(card);

  const place = (at: PortalPoint | null): void => {
    if (at === null) {
      card.style.left = '50%';
      card.style.top = 'calc(50% + 18px)';
      card.style.transform = 'translateX(-50%)';
      return;
    }
    const view = doc.defaultView;
    const corner = cardCorner(
      at,
      { width: card.offsetWidth, height: card.offsetHeight },
      { width: view?.innerWidth || Infinity, height: view?.innerHeight || Infinity },
    );
    card.style.left = `${corner.left}px`;
    card.style.top = `${corner.top}px`;
    card.style.transform = 'none';
  };

  return {
    showFocus(text, href, at) {
      if (disposed) return;
      name.textContent = text;
      const host = doorSite(href);
      site.textContent = host === '' ? '' : `On ${host}`;
      site.style.display = host === '' ? 'none' : 'block';
      // Shown before it is placed: its size, which says whether it fits beside the pointer, is known only then.
      card.style.display = 'block';
      place(at);
    },
    placeFocus(at) {
      if (!disposed) place(at);
    },
    hideFocus() {
      if (!disposed) card.style.display = 'none';
    },
    setReticleVisible(visible) {
      if (!disposed) reticle.style.display = visible ? 'block' : 'none';
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      card.remove();
      reticle.remove();
    },
  };
}
